/* 更新のお知らせ。直したこと・足したことを、上が新しい順で並べる。

   使い方：手を入れたら、いちばん上に1件足す。
   - v は日付＋その日の通し番号。これが「見たかどうか」の目印になる
   - k は「追加」か「修正」
   - t は現場の人が読んで分かる一言。何の画面の話かが分かるように書く */

export type ChangeKind = "追加" | "修正";

export type Change = { k: ChangeKind; t: string };

export type Release = {
  /** 目印。日付＋その日の通し番号 */
  v: string;
  /** 表示する日付 */
  d: string;
  /** 見出し */
  title: string;
  items: Change[];
};

