    title: "フォークリフト（最大荷重1トン未満）の特別教育を出しました（学科6時間＋実技6時間）",
    items: [
      { k: "追加", t: "**フォークリフト（最大荷重1トン未満）の運転の業務に係る特別教育**を出しました。ホームの「その他特別教育」から選べます。学科6時間・4科目14単元。6,000円（税抜）" },
      { k: "追加", t: "**倉庫・工場・小売・農業・市場・港湾・建設の資材ヤード。**どの業種にもある機械です。1トン以上は技能講習で、この教育では乗れません。線は銘板の最大荷重で見る、と繰り返しています" },
      { k: "追加", t: "科目・範囲・時間は**安全衛生特別教育規程第7条の表のまま**（走行装置2時間／荷役装置2時間／力学1時間／関係法令1時間）。力学は告示の中欄7つ（力・重量・重心と安定・速度と加速度・荷重・応力・材料の強さ）を1つずつ単元にしました" },
      { k: "追加", t: "学科のあとに**実技6時間**（走行の操作4時間・荷役の操作2時間）が残ります。6つの段取りの案と実施記録の様式を用意しました（/edu/forklift/drill から印刷できます）" },
      { k: "追加", t: "後ろの車輪で曲がる、前が重い、止まりにくい。乗用車と違う三つを、事例と実技の段取りで体に入れる作りです" },
    ],
